export async function getInventory() {
  await connection()
  return {
    count: Math.floor(Math.random() * 50),
    price: (Math.random() * 100).toFixed(2),
  }
}
import type { Metadata } from 'next'

export const metadata: Metadata = {
  title: 'Shop',
  description: 'E-commerce product store',
}

